const clone = <T>(x: T): T => JSON.parse(JSON.stringify(x)) as T;
/** A deep copy with keys replaced — a TEST MUTATION (CONSTRUCTED). */
const mutate = <T>(x: T, patch: Record<string, unknown>): T => ({ ...clone(x), ...patch });

/** REAL. */
const finalDetail = fixtures.finalDetail as unknown as EventDetailResponse;
const finalHistory = fixtures.finalHistory as unknown as EventHistoryResponse;
const finalMarkets = fixtures.finalMarkets as unknown as GameMarketsResponse;

/** REAL: the capture's own retrieval instant (native `finalNow`). */
const FINAL_NOW = "2026-10-11T04:57:23.592725Z";
/** CONSTRUCTED (native): one minute before first pitch; the served consensus row's own stamp. */
const BEFORE_NOW = "2026-09-30T20:59:00Z";
const BEFORE_OBSERVED = "2026-09-30T20:58:00Z";
/** CONSTRUCTED (native): 33 s after the served `current_odds.captured_at`, which is the host clock. */
const LIVE_NOW = "2026-10-01T00:16:30Z";
const LIVE_OBSERVED = "2026-10-01T00:15:57.061753Z";
/** CONSTRUCTED (native `liveHistoryNow`): mid-game, for the history cut. */
const LIVE_HISTORY_NOW = "2026-09-30T22:13:00Z";

/** CONSTRUCTED: native `liveEdits`, key for key, over the real final. */
