describe("LIVE — CONSTRUCTED from the final (native liveEdits)", () => {
  const view = build(liveDetail, LIVE_NOW, liveHostRest());
  const { matrix } = view.headline;

  it("keeps pregame chance, current chance (lead), runs and the projected final in one aligned comparison", () => {
    expect(view.phase).toBe("live");
    expect(view.scope).toBe("mlb:15321836:live");
    expect(matrix.columns.map((c) => c.title)).toEqual([
      MATRIX_WORDS.pregameChance,
      MATRIX_WORDS.currentChance,
      MLB_WORDS.runs,
      "Projected final",
    ]);
    expect(matrix.lead).toBe(1);
    expect(matrix.groups).toEqual([
      [0, 1],
      [2, 3],
    ]);
    const [home, away] = matrix.rows;
    expect(texts(home.values).slice(0, 3)).toEqual(["59%", "<1%", "3"]);
    expect(texts(away.values).slice(0, 3)).toEqual(["41%", ">99%", "7"]);
    expect(matrix.columns[1].provenance).toBe(`Recorded ${stamp(LIVE_OBSERVED)}`);
    expect(matrix.columns[2].provenance).toBe(`Score observed ${stamp(LIVE_OBSERVED)}`);
  });

  it("with no inning served it says Live and Inning unavailable; with one, the inning from ESPN (no 0:00)", () => {
    expect(view.headline.state).toBe("Live");
    expect(view.headline.stateContext).toBe("Inning unavailable");
    // TEST MUTATION: an ESPN game state of the kind the real history's stat_model rows carry.
    const v = build(mutate(liveDetail, { espn: { period: "Middle 3rd", game_clock: "0:00" } }), LIVE_NOW, liveHostRest());
    expect(v.headline.state).toBe("Middle 3rd");
    expect(v.headline.stateContext).toBe(MATRIX_WORDS.stateSource);
  });

  it("the runs and the projected final are ONE displayed pair: the host's, not the event row", () => {
    // CONSTRUCTED (#8278's shape): the event row lags at 1–0 while the page displays 3–6 from its chart
    // arm, and the page admitted a projected final reachable from THAT pair (4 ≥ 3, 7 ≥ 6).
    const lagging = mutate(liveDetail, { home_score: 1, away_score: 0 });
    const rest = liveHostRest({ score: { home: 3, away: 6, observedAt: LIVE_OBSERVED }, projectedFinal: { home: 4, away: 7 } });
    const v = build(lagging, LIVE_NOW, rest);
    const runs = column(v, MLB_WORDS.runs);
    const projected = column(v, "Projected final");
    expect([runs.home.text, runs.away.text]).toEqual(["3", "6"]);
    expect([projected.home.text, projected.away.text]).toEqual(["4", "7"]);
    // The page's reachability comparison holds for exactly the pair printed beside it.
    expect(Number(projected.home.text)).toBeGreaterThanOrEqual(Number(runs.home.text));
    expect(Number(projected.away.text)).toBeGreaterThanOrEqual(Number(runs.away.text));
    // Whatever the row says, the section prints the same thing: it never reads the row's score.
    const otherRow = build(mutate(liveDetail, { home_score: 8, away_score: 8 }), LIVE_NOW, rest);
    expect(otherRow.headline.matrix).toEqual(v.headline.matrix);
  });

  it("the stoppage filler (host score null) prints Score unavailable for both teams", () => {
    const v = build(liveDetail, LIVE_NOW, liveHostRest({ score: null }));
    const runs = column(v, MLB_WORDS.runs);
    expect([runs.home.text, runs.away.text]).toEqual([MLB_WORDS.scoreUnavailable, MLB_WORDS.scoreUnavailable]);
    expect(runs.provenance).toBeNull();
  });

  it("a null projection is honest absence: Projected final unavailable", () => {
    const p = column(view, "Projected final");
    expect([p.home.text, p.away.text]).toEqual([MLB_WORDS.projectionUnavailable, MLB_WORDS.projectionUnavailable]);
  });

  it("the final's wording stays the final's: during play the column is still Projected final, never Unavailable", () => {
    const titles = view.headline.matrix.columns.map((c) => c.title);
    expect(titles).not.toContain(MLB_WORDS.pregameProjectedFinal);
    expect(view.headline.matrix.rows.flatMap((r) => texts(r.values))).not.toContain(MLB_WORDS.unavailable);
    const before = build(beforeDetail, BEFORE_NOW, beforeHostRest());
    expect(before.headline.matrix.columns.map((c) => c.title)).toEqual([MATRIX_WORDS.currentChance, "Projected final"]);
    expect(before.headline.matrix.rows.flatMap((r) => texts(r.values))).not.toContain(MLB_WORDS.unavailable);
  });

  it("an unbacked live claim: No result reported over the displayed pair, last recorded chance, projection withheld", () => {
    // CONSTRUCTED: the page's own answer says unbacked, and an inconsistent host still hands a pair over.
    const rest = liveHostRest({ liveClaimUnbacked: true, projectedFinal: { home: 4, away: 8 } });
    const v = build(liveDetail, LIVE_NOW, rest);
    expect(v.headline.state).toBe(`${SUSPENDED_LABEL} · last score 7-3`);
    expect(v.headline.stateContext).toBeNull();
    expect(v.headline.matrix.columns[1].title).toBe(MATRIX_WORDS.lastRecordedChance);
    const p = column(v, "Projected final");
    expect([p.home.text, p.away.text]).toEqual([MLB_WORDS.projectionWithheld, MLB_WORDS.projectionWithheld]);
  });

  it("stale, undated and interrupted readings are never Current; exactly 30 minutes still is", () => {
    const now = Date.parse(LIVE_NOW);
    const titleAt = (patch: Partial<MlbGameHost>) =>
      build(liveDetail, LIVE_NOW, liveHostRest(patch)).headline.matrix.columns[1].title;
    // CONSTRUCTED host clocks.
    expect(titleAt({ probabilityObservedAt: new Date(now - 30 * 60_000).toISOString() })).toBe(MATRIX_WORDS.currentChance);
    expect(titleAt({ probabilityObservedAt: new Date(now - 30 * 60_000 - 1).toISOString() })).toBe(
      MATRIX_WORDS.lastRecordedChance,
    );
    expect(titleAt({ probabilityObservedAt: null })).toBe(MATRIX_WORDS.lastRecordedChance);
    expect(titleAt({ deliveryInterrupted: true })).toBe(MATRIX_WORDS.lastRecordedChance);
  });

  it("a game the venue settled while not finished prints no chance at all (native showsVenueSettledVerdict)", () => {
    const v = build(mutate(liveDetail, { venue_settled: true }), LIVE_NOW, liveHostRest()); // TEST MUTATION
    const current = v.headline.matrix.rows.map((r) => r.values[1]);
    expect(texts(current)).toEqual([MLB_WORDS.winChanceUnavailable, MLB_WORDS.winChanceUnavailable]);
  });

  it("no hero and no pregame reading leave each slot's own words — never a fabricated away chance", () => {
    const bare = mutate(liveDetail, { prematch_odds: null, opening_odds: null }); // TEST MUTATION
    const v = build(bare, LIVE_NOW, liveHostRest(), {}, null);
    const [home, away] = v.headline.matrix.rows;
    expect(texts(home.values).slice(0, 2)).toEqual([MLB_WORDS.pregameChanceUnavailable, MLB_WORDS.winChanceUnavailable]);
    expect(texts(away.values).slice(0, 2)).toEqual([MLB_WORDS.pregameChanceUnavailable, MLB_WORDS.winChanceUnavailable]);
    // A hero with a home figure and no away figure prints neither (no 1 − home).
    const halfHero = { homeProb: 0.4, awayProb: null, homePct: 40, awayPct: null, probSourceLabel: null };
    const half = build(liveDetail, LIVE_NOW, liveHostRest(), {}, halfHero);
    expect(texts(half.headline.matrix.rows.map((r) => r.values[1]))).toEqual([
      MLB_WORDS.winChanceUnavailable,
      MLB_WORDS.winChanceUnavailable,
    ]);
  });
});

