describe("the history is H2's, unchanged, over this game's own body only", () => {
  const view = build(finalDetail, FINAL_NOW, finalHostRest());
  const h = view.history;

  it("is exactly hockeyJourneyHistory's answer for the same inputs (gap, clock and complement disclosures intact)", () => {
    expect(h).toEqual(hockeyJourneyHistory(finalHistory, finalDetail, "final", Date.parse(FINAL_NOW)));
    expect(view.historyForeign).toBe(false);
    expect(h.line).toBe("blend");
    expect(h.series.map((s) => s.id)).toEqual([
      historySeriesId("blend", 15321836, "home"),
      historySeriesId("blend", 15321836, "away"),
    ]);
    expect(h.notes).toEqual(
      expect.arrayContaining([complementNote("Chicago White Sox", "Houston Astros"), HISTORY_WORDS.gapsNote]),
    );
  });

  it("draws the game, clipped at the page chart's own end, without the settlement row", () => {
    expect(h.domain).not.toBeNull();
    expect(h.absence).toBeNull();
    const end = historyGameEnd(finalHistory, finalDetail);
    expect(end).not.toBeNull();
    expect(h.domain!.upper).toBeLessThanOrEqual(end!);
    // The served blend ends with the settlement row (0.0, re-stamped 00:18:00 after a real 00:18:00 reading).
    const rows = finalHistory.aggregate_line!;
    const settlement = rows.length - 1;
    expect(rows[settlement].home_probability).toBe(0);
    const drawn = h.series.flatMap((s) => s.runs.flat());
    expect(drawn.length).toBeGreaterThan(0);
    expect(drawn.some((p) => p.row === settlement)).toBe(false);
    expect(drawn.some((p) => p.p === 0 || p.p === 1)).toBe(false);
  });

  it("draws no inning guide: the body serves half-inning markers, and none is admitted or invented", () => {
    expect((finalHistory.period_markers ?? []).length).toBeGreaterThan(0);
    expect(h.guides.filter((g) => g.kind === "period")).toEqual([]);
  });

  it("another event's body reads exactly as a missing one: History unavailable, nothing borrowed", () => {
    const foreign = build(finalDetail, FINAL_NOW, finalHostRest(), { history: mutate(finalHistory, { event_id: 15321837 }) });
    const missing = build(finalDetail, FINAL_NOW, finalHostRest(), { history: null });
    expect(foreign.historyForeign).toBe(true);
    expect(missing.historyForeign).toBe(false);
    expect(foreign.history).toEqual(missing.history);
    expect(foreign.history.absence).toEqual({ title: HISTORY_WORDS.historyUnavailable, words: null });
    expect(foreign.history.series.every((s) => s.runs.length === 0)).toBe(true);
    // The headline does not depend on the history body.
    expect(foreign.headline).toEqual(view.headline);
  });

  it("CONSTRUCTED live cut: nothing after now is drawn, and the readout names before and recorded", () => {
    const now = Date.parse(LIVE_HISTORY_NOW);
    const v = build(liveDetail, LIVE_HISTORY_NOW, liveHostRest({ probabilityObservedAt: null }));
    const points = v.history.series.flatMap((s) => s.runs.flat());
    expect(points.length).toBeGreaterThan(0);
    expect(points.every((p) => p.t <= now)).toBe(true);
    expect(v.history.readout).toBe("beforeAndRecorded");
  });
});

