describe("pure: same inputs, same answer, nothing mutated", () => {
  it("builds the same model twice and leaves every body untouched", () => {
    const before = JSON.stringify([finalDetail, finalHistory, finalMarkets]);
    const a = build(liveDetail, LIVE_NOW, liveHostRest({ projectedFinal: { home: 4, away: 8 } }));
    const b = build(liveDetail, LIVE_NOW, liveHostRest({ projectedFinal: { home: 4, away: 8 } }));
    expect(a).toEqual(b);
    expect(JSON.stringify([finalDetail, finalHistory, finalMarkets])).toBe(before);
  });
});
